  height: Math.max(400, dash_data.summary.numRows() * 40),
  color: { domain: ["Target", "Modeled"], range: [themeTarget, themeModel], legend: true, label: "Data Source" },
  style: { backgroundColor: 'transparent', fontFamily: "Inter, system-ui, sans-serif" },
