function fmtVmt(value) {
  if (typeof value === 'undefined' || value === null || Number.isNaN(value)) return '';
  return Math.round(value).toLocaleString();
}
function fmtPct(value) {
  if (typeof value === 'undefined' || value === null || Number.isNaN(value)) return '';
  return (value * 100).toFixed(1) + '%';
}

// One group per geography (Region + counties), each with its Freeway /
// Non-Freeway rows plus an "All Roadways" subtotal row.
tableGroups = countyOrder.map(county =&gt; {
  const fips = Array.from(countyNames).find(([, name]) =&gt; name === county)[0];
  const rows = vmtT
    .filter(d =&gt; d.ClassLevel === 'FTGROUP' && d.vehType === bVehType && d.calib_run === globalCalibRun && d.CO_FIPS === fips)
    .map(d =&gt; ({ClassLabel: classLabels.get(d.FTCLASS) ?? d.FTCLASS, VMT_Mod: d.VMT_Mod, VMT_Target: d.VMT_Target, vmtDiff: d.vmtDiff, vmtDiffPct: d.vmtDiffPct}))
    .sort((a, b) =&gt; a.ClassLabel === 'Freeway' ? -1 : b.ClassLabel === 'Freeway' ? 1 : 0);
  const modSum = d3.sum(rows, d =&gt; d.VMT_Mod);
  const targetSum = d3.sum(rows, d =&gt; d.VMT_Target);
  const subtotal = {
    ClassLabel: 'All Roadways',
    VMT_Mod: modSum,
    VMT_Target: targetSum,
    vmtDiff: modSum - targetSum,
    vmtDiffPct: targetSum ? (modSum - targetSum) / targetSum : undefined
  };
  return {County: county, rows: [...rows, subtotal]};
})























