      tmeErrorPct: (m.total_trips - o.total_trips) / o.total_trips
    };
  }).filter(d =&gt; d !== null);
}

// 3. FINAL FILTERING
dc_filtered_2 = dc_2.filter(d =&gt; d.Source === vSource_2)

// 4. NOTEBOOK-MATCHED METRICS
slope_through_origin = (rows) =&gt; {
  const denominator = d3.sum(rows, d =&gt; d.tmeObs * d.tmeObs);
  return denominator &gt; 0
    ? d3.sum(rows, d =&gt; d.tmeObs * d.tmeMod) / denominator
    : 0;
}

wmape = (rows) =&gt; {
  const totalObs = d3.sum(rows, d =&gt; d.tmeObs);
  return totalObs &gt; 0
    ? d3.sum(rows, d =&gt; Math.abs(d.tmeMod - d.tmeObs)) / totalObs
    : 0;
}

