vo_filtered_base = transpose(val_data_ojs).filter(row =&gt;
  row.GeoLevel === geo_level && row.calib_run === globalCalibRun
)

// Aggregate by GeoName × HHSize × VehOwn
vo_agg_facet = {
  const grouped = d3.groups(vo_filtered_base, d =&gt; d.GeoName, d =&gt; d.HHSize, d =&gt; d.VehOwn);
  const rows = [];
  for (const [GeoName, bySize] of grouped) {
    for (const [hhsize, byVeh] of bySize) {
      for (const [vehown, records] of byVeh) {
        const mod = d3.sum(records, d =&gt; d.Model_HH);
        const acs = d3.sum(records, d =&gt; d.ACS_HH);
        const hts = d3.sum(records, d =&gt; d.HTS_HH);
        rows.push({
          GeoName, HHSize: hhsize, VehOwn: vehown,
          Model_HH: mod, ACS_HH: acs, HTS_HH: hts,
          Pct_Error:      acs &gt; 0 ? (mod - acs) / acs : 0,
          Pct_Error_HTS:  hts &gt; 0 ? (mod - hts) / hts : 0,
          Pct_ACS_vs_Mod: mod &gt; 0 ? (acs - mod) / mod : 0,
          Pct_HTS_vs_Mod: mod &gt; 0 ? (hts - mod) / mod : 0,
          Pct_ACS_vs_HTS: hts &gt; 0 ? (acs - hts) / hts : 0,
          Pct_HTS_vs_ACS: acs &gt; 0 ? (hts - acs) / acs : 0,
        });
      }
    }
  }
  // Normalise each source by its own grand total
  const totMod = d3.sum(rows, d =&gt; d.Model_HH);
  const totAcs = d3.sum(rows, d =&gt; d.ACS_HH);
  const totHts = d3.sum(rows, d =&gt; d.HTS_HH);
  return rows.map(r =&gt; ({
    ...r,
    Model_Pct:  totMod &gt; 0 ? r.Model_HH / totMod : 0,
    ACS_Pct:    totAcs &gt; 0 ? r.ACS_HH   / totAcs : 0,
    HTS_Pct_vo: totHts &gt; 0 ? r.HTS_HH   / totHts : 0,
  }));
}

