        Pct_ACS_vs_Mod: mod &gt; 0 ? (acs - mod) / mod : null,
        Pct_HTS_vs_Mod: mod &gt; 0 ? (hts - mod) / mod : null,
        Pct_ACS_vs_HTS: hts &gt; 0 ? (acs - hts) / hts : null,
        Pct_HTS_vs_ACS: acs &gt; 0 ? (hts - acs) / acs : null,
      };
    },
    d =&gt; d.GeoName
  );

