        `&lt;span style="display:inline-block;width:14px;height:14px;border-radius:2px;flex-shrink:0;` +
                     `background:${getColor(v)};border:1px solid rgba(0,0,0,0.15);"&gt;&lt;/span&gt;` +
        `&lt;span style="font-size:11px;"&gt;${labels[i]}&lt;/span&gt;` +
      `&lt;/div&gt;`
    ).join("");
